var t=`0213-escalivada`;var a=`world-0213`;var n=`ES`;var r=`southern-europe`;var l=4;var s=48;var o={en:`Escalivada`,ua:`Ескалівада`};var d={en:`A traditional Spain dish made with eggplant, red bell pepper, yellow onion, sherry vinegar. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Іспанія. Основні інгредієнти: баклажан, червоний солодкий перець, жовта цибуля, хересний оцет. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Cut the vegetables evenly and roast at 200°C for about 40 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 40 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:40,i:[[`eggplant`,450,`g`],[`red-bell-pepper`,400,`g`],[`yellow-onion`,250,`g`],[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:5,i:[]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:3,i:[[`sherry-vinegar`,15,`ml`],[`garlic`,1,`clove`],[`extra-virgin-olive-oil`,40,`ml`],[`table-salt`,null,`to_taste`]]}];var p={slug:t,id:a,country:`ES`,region:r,servings:4,minutes:48,title:o,text:d,steps:g};export{n as country,p as default,a as id,s as minutes,r as region,l as servings,t as slug,g as steps,d as text,o as title};